package desktop

import (
	"fmt"
	"net/http"
)

func (h *Host) ExpireBootstrap() { h.mu.Lock(); h.Bootstrap = ""; h.mu.Unlock() }
func (h *Host) setup(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Content-Security-Policy", "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; object-src 'none'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'")
	fmt.Fprint(w, setupHTML)
}

const setupHTML = `<!doctype html><html><head><meta charset="utf-8"><title>Picofarm desktop settings</title><style>body{font:16px system-ui;max-width:650px;margin:3rem auto;padding:1rem}label{display:block;margin:1rem 0}input[type=url],input[type=password]{width:100%;padding:.5rem}button{padding:.6rem}#result{white-space:pre-wrap}</style></head><body><h1>Desktop settings</h1><p>One active mode. Saving requires quitting and reopening Picofarm. Local data remains on this device when using remote mode.</p><form id="settings"><label>Mode <select id="mode"><option value="local">Local</option><option value="remote">Remote server</option></select></label><label>Remote server origin <input id="remoteURL" type="url" placeholder="https://picofarm.example.com"></label><label>Remote API token <input id="remoteToken" type="password" autocomplete="off" placeholder="Leave blank to retain token for unchanged server"></label><label><input id="allowInsecureLoopback" type="checkbox">Allow HTTP for a literal loopback address (development only)</label><label><input id="closeToTray" type="checkbox">Close to tray (Linux currently quits to avoid an unreachable app)</label><fieldset><legend>Native notifications</legend><label><input id="finished" type="checkbox">Finished</label><label><input id="failed" type="checkbox">Failed</label><label><input id="critical" type="checkbox">Critical</label></fieldset><label><input id="autostart" type="checkbox">Start Picofarm when signing in (disabled by default)</label><p>Updates are never installed automatically. Check releases using the tray menu.</p><button>Save settings</button> <a href="/">Back to Picofarm</a></form><p id="result" role="status"></p><script>const ids=['mode','remoteURL','allowInsecureLoopback','closeToTray','autostart'];let config;fetch('/desktop/config').then(r=>r.json()).then(c=>{config=c;for(const id of ids){const e=document.getElementById(id);if(e.type==='checkbox')e.checked=c[id];else e.value=c[id]||''}for(const id of ['finished','failed','critical'])document.getElementById(id).checked=!!c.notifications[id]}).catch(()=>{document.getElementById('result').textContent='Could not load settings'});document.getElementById('settings').onsubmit=async e=>{e.preventDefault();if(!config)return;for(const id of ids){const el=document.getElementById(id);config[id]=el.type==='checkbox'?el.checked:el.value}config.remoteToken=document.getElementById('remoteToken').value;config.notifications={};for(const id of ['finished','failed','critical'])config.notifications[id]=document.getElementById(id).checked;try{const r=await fetch('/desktop/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(config)});if(!r.ok)throw new Error(await r.text());document.getElementById('remoteToken').value='';document.getElementById('result').textContent='Saved. Quit and reopen Picofarm to apply.'}catch(err){document.getElementById('result').textContent=String(err)}};</script></body></html>`
